const gespann = (fg = BLACK, bg = WHITE) => `<g transform="translate(0 18) scale(0.64)">${horse(fg)}</g><path d="M46 56 H60" stroke="${fg}" stroke-width="4"/><rect x="58" y="38" width="36" height="22" rx="2" fill="${fg}"/><circle cx="76" cy="68" r="13" fill="${fg}"/><circle cx="76" cy="68" r="4" fill="${bg}"/>`;
const cow = (fg = BLACK) => `<path d="M24 42 H74 Q84 42 84 52 V66 H24 Z" fill="${fg}"/><path d="M26 46 L12 40 L4 48 L8 60 L24 62 Z" fill="${fg}"/><path d="M12 40 L6 30 M19 41 L22 30" stroke="${fg}" stroke-width="3" stroke-linecap="round"/><path d="M32 66 V88 M42 66 V88 M64 66 V88 M76 66 V88" stroke="${fg}" stroke-width="6" stroke-linecap="round"/><path d="M84 46 Q94 52 90 68" stroke="${fg}" stroke-width="3" stroke-linecap="round" fill="none"/><ellipse cx="58" cy="70" rx="7" ry="5" fill="${fg}"/>`;
const escooter = (fg = BLACK, bg = WHITE) => `<rect x="18" y="66" width="50" height="7" rx="2" fill="${fg}"/><circle cx="16" cy="76" r="9" fill="${fg}"/><circle cx="16" cy="76" r="3" fill="${bg}"/><circle cx="74" cy="76" r="9" fill="${fg}"/><circle cx="74" cy="76" r="3" fill="${bg}"/><path d="M22 66 L36 20" stroke="${fg}" stroke-width="6" stroke-linecap="round"/><path d="M26 20 H46" stroke="${fg}" stroke-width="5" stroke-linecap="round"/>`;
const moped = (fg = BLACK) => `<circle cx="22" cy="70" r="12" fill="none" stroke="${fg}" stroke-width="5"/><circle cx="76" cy="70" r="12" fill="none" stroke="${fg}" stroke-width="5"/><path d="M22 70 L38 44 H58 L76 70 M38 44 L34 32 H24 M58 44 L61 36 H74 M46 44 L40 70" fill="none" stroke="${fg}" stroke-width="5" stroke-linejoin="round" stroke-linecap="round"/><rect x="42" y="52" width="16" height="12" rx="2" fill="${fg}"/><rect x="52" y="35" width="14" height="6" rx="2" fill="${fg}"/>`;
const pedChild = (fg = BLACK) => `<g transform="translate(-14 -2) scale(0.98)">${P.pedestrian.replaceAll(BLACK, fg)}</g><circle cx="69" cy="42" r="6" fill="${fg}"/><path d="M63 50 H75 L80 64 L75 65 L72 56 V68 L78 86 L71 88 L66 74 L61 88 L54 86 L60 68 V56 L57 65 L52 64 Z" fill="${fg}"/>`;
const snowChain = `<defs><clipPath id="tread"><path d="M50 12 A40 40 0 1 0 50 92 A40 40 0 1 0 50 12 Z M50 26 A26 26 0 1 1 50 78 A26 26 0 1 1 50 26 Z" clip-rule="evenodd"/></clipPath></defs><circle cx="50" cy="52" r="33" fill="none" stroke="${WHITE}" stroke-width="14"/><circle cx="50" cy="52" r="10" fill="${WHITE}"/><g clip-path="url(#tread)" stroke="${BLUE}" stroke-width="2.5" fill="none">${[-4, -3, -2, -1, 0, 1, 2, 3, 4].map((i) => `<path d="M${-10 + i * 11 + 2} 112 L${110 + i * 11 + 2} 12 M${110 - i * 11 - 2} 112 L${10 - i * 11 - 2} 12"/>`).join("")}</g>`;
const truckHazard = `${P.truckFront}<rect x="34" y="54" width="32" height="14" fill="${ORANGE}" stroke="${BLACK}" stroke-width="2"/>`;
const truckWater = `${P.truckFront}<path d="M30 58 q5 -5 10 0 t10 0 t10 0 t10 0 M30 68 q5 -5 10 0 t10 0 t10 0 t10 0" fill="none" stroke="${WHITE}" stroke-width="3" stroke-linecap="round"/>`;
const axle = `<rect x="16" y="66" width="16" height="16" rx="2" fill="${BLACK}"/><rect x="68" y="66" width="16" height="16" rx="2" fill="${BLACK}"/><rect x="32" y="71" width="36" height="6" fill="${BLACK}"/>`;

// Fahrtrichtungspfeile (weiß, 100×100)
const arrowUp = P.arrowUpWhite;
const arrowRot = (deg) => `<g transform="rotate(${deg} 50 50)">${arrowUp}</g>`;
const bentLeft = `<path d="M58 92 V46 Q58 34 46 34 H30" fill="none" stroke="${WHITE}" stroke-width="15"/><path d="M34 14 L8 34 L34 54 Z" fill="${WHITE}"/>`;
