const leftOrRight = `<path d="M50 92 V64 Q50 48 36 48 H28 M50 64 Q50 48 64 48 H72" fill="none" stroke="${WHITE}" stroke-width="13"/><path d="M30 32 L6 48 L30 64 Z M70 32 L94 48 L70 64 Z" fill="${WHITE}"/>`;

// ---------------------------------------------------------------------------------------------
// Zeichenformen für diese Gruppe
// ---------------------------------------------------------------------------------------------
/** Andreaskreuz: stehend (Arme 45°) oder liegend (Arme 30°), optional mit Blitzpfeil (Oberleitung) */
function andreaskreuz(liegend, blitz, title) {
  const arm = (rot) => `<g transform="rotate(${rot} 60 60)"><rect x="6" y="49" width="108" height="22" fill="${WHITE}" stroke="${BLACK}" stroke-width="1.5"/><rect x="6" y="49" width="30" height="22" fill="${RED}"/><rect x="84" y="49" width="30" height="22" fill="${RED}"/></g>`;
  const a = liegend ? 30 : 45;
  const bolt = blitz ? `<path d="M61 42 L52 62 H59 L54 80 L69 57 H62 L68 42 Z" fill="${BLACK}"/>` : "";
  return `${svgOpen(120, 120, title)}${arm(a)}${arm(-a)}${bolt}</svg>`;
}
/** Halteverbot mit roten Balken ("x" = absolut, "\\" = eingeschränkt) und optionalen weißen Pfeilen (Anfang/Ende/Mitte) */
function halt(kind, arrows, title) {
  const bar = (rot) => `<rect x="54" y="0" width="12" height="120" fill="${RED}" transform="rotate(${rot} 60 60)"/>`;
  const bars = kind === "x" ? bar(45) + bar(-45) : bar(-45);
  let ar = "";
  if (kind === "x") {
    if (arrows === "10" || arrows === "30") ar += `<path d="M78 55 H88 V46 L104 60 L88 74 V65 H78 Z" fill="${WHITE}"/>`;
    if (arrows === "20" || arrows === "30") ar += `<path d="M42 55 H32 V46 L16 60 L32 74 V65 H42 Z" fill="${WHITE}"/>`;
  } else {
    if (arrows === "10" || arrows === "30") ar += `<path d="M64 38 H84 V28 L100 42 L84 56 V46 H64 Z" fill="${WHITE}"/>`;
    if (arrows === "20" || arrows === "30") ar += `<path d="M56 82 H36 V92 L20 78 L36 64 V74 H56 Z" fill="${WHITE}"/>`;
  }
  return `${svgOpen(120, 120, title)}<defs><clipPath id="hv"><circle cx="60" cy="60" r="57"/></clipPath></defs><circle cx="60" cy="60" r="57" fill="${BLUE}" stroke="#9CA3AF" stroke-width="1"/><g clip-path="url(#hv)">${bars}</g><circle cx="60" cy="60" r="57" fill="none" stroke="${RED}" stroke-width="13"/>${ar}</svg>`;
}
/** Inneres eines Halteverbots als Piktogramm für Zonenschilder (120er-Raster, ohne Rahmenkontur) */
const haltInner = (fill = BLUE, barFill = RED) => `<defs><clipPath id="zc"><circle cx="60" cy="60" r="57"/></clipPath></defs><circle cx="60" cy="60" r="57" fill="${fill}"/><g clip-path="url(#zc)"><rect x="54" y="0" width="12" height="120" fill="${barFill}" transform="rotate(-45 60 60)"/></g><circle cx="60" cy="60" r="50.5" fill="none" stroke="${barFill}" stroke-width="13"/>`;
/** Blauer Kreis als eingebettetes Piktogramm (120er-Raster) */
const blueDisc = (inner, fill = BLUE, size = 76) => `<circle cx="60" cy="60" r="57" fill="${fill}"/><circle cx="60" cy="60" r="53" fill="none" stroke="${WHITE}" stroke-width="3"/>${pict(inner, 60 - size / 2, 60 - size / 2, size)}`;
/** Roter Ring als eingebettetes Piktogramm (120er-Raster) */
const redDisc = (inner, ring = RED, size = 68) => `<circle cx="60" cy="60" r="57" fill="${ring}"/><circle cx="60" cy="60" r="44" fill="${WHITE}"/>${pict(inner, 60 - size / 2, 60 - size / 2, size)}`;
/** Schwarzer Schrägstrich über einem Zonenschild (Ende) */
const endStripe = (w, h) => `<path d="M16 ${h - 16} L${w - 16} 16" stroke="${BLACK}" stroke-width="6" stroke-linecap="round"/>`;
/** Weißes Rechteck mit eingebettetem Scheibenpiktogramm und Text (Zonen- und Straßenschilder) */
function zoneSign(w, h, disc, discSize, label, labelSize, title, { top = 18, ende = false, header = "" } = {}) {
  const inner = `${header}<svg x="${(w - discSize) / 2}" y="${top}" width="${discSize}" height="${discSize}" viewBox="0 0 120 120">${disc}</svg>${text(w / 2, h - 22, labelSize, label, ende ? GREY : BLACK)}${ende ? endStripe(w, h) : ""}`;
  return rectWhite(w, h, inner, title);
}
/** Blaues Quadrat mit drei Fahrstreifen (Seitenstreifen rechts) */
function seitenstreifen(kind, title) {
  const lane = `stroke="${WHITE}" stroke-width="3"`;
  const arrow = (x) => `<path d="M${x} 100 V40 M${x} 24 L${x - 9} 42 H${x + 9} Z" ${lane} fill="${WHITE}" stroke-linejoin="round"/>`;
  let inner = `<path d="M18 12 V108" ${lane}/><path d="M46 12 V108" ${lane} stroke-dasharray="8 6"/><path d="M74 12 V108" ${lane}/><path d="M102 12 V108" ${lane}/>${arrow(32)}${arrow(60)}`;
  if (kind === 1) inner += arrow(88);
  const bend = `fill="none" stroke="${WHITE}" stroke-width="3.5"`;
  if (kind === 2) inner += `<path d="M88 100 V60 Q88 46 78 46 H76" ${bend}/><path d="M78 36 L64 46 L78 56 Z" fill="${WHITE}"/>`;
  if (kind === 3) inner += `<path d="M88 100 V78 Q88 66 78 66 H76" ${bend}/><path d="M78 56 L64 66 L78 76 Z" fill="${WHITE}"/><path d="M76 14 L100 38 M76 26 L100 50 M76 38 L100 62" stroke="${WHITE}" stroke-width="2.5"/>`;
  return rectBlue(120, 120, inner, title);
}
/** Fahrbahnmarkierung: weiße Markierung auf grauem Asphalt (120×120) */
const marking = (inner, title) => `${svgOpen(120, 120, title)}<rect x="0" y="0" width="120" height="120" rx="6" fill="${ASPHALT}"/>${inner}</svg>`;
const laneEdges = `<path d="M8 0 V120 M112 0 V120" stroke="${WHITE}" stroke-width="3"/>`;

/** Ein Tempo-Zeichen 274 mit Zahl */
const tempo = (v) => ({
  id: `274-${v}`, number: `274-${v}`, name: `Zulässige Höchstgeschwindigkeit ${v} km/h`, category: cat,
  meaning: `Es darf nicht schneller als ${v} km/h gefahren werden. Das Verbot gilt ab dem Zeichen bis zu seiner Aufhebung, bis zur nächsten Kreuzung oder Einmündung oder bis zu einem Zeichen mit anderer Geschwindigkeit; ein Zusatzzeichen kann es beschränken, etwa auf eine Fahrzeugart oder auf bestimmte Zeiten.`,
  alt: `Zeichen 274 Zulässige Höchstgeschwindigkeit ${v} km/h: roter Ring mit schwarzer ${v}`,
  svg: () => circleRed(text(50, String(v).length > 2 ? 66 : 68, String(v).length > 2 ? 40 : 50, String(v)), `Zeichen 274 Zulässige Höchstgeschwindigkeit ${v} km/h`, 100),
});
/** Ende der zulässigen Höchstgeschwindigkeit 278 mit Zahl */
const tempoEnd = (v) => ({
  id: `278-${v}`, number: `278-${v}`, name: `Ende der zulässigen Höchstgeschwindigkeit ${v} km/h`, category: cat,
  meaning: `Hebt die zuvor angeordnete Höchstgeschwindigkeit von ${v} km/h auf. Danach gilt wieder die allgemeine Höchstgeschwindigkeit (innerorts 50 km/h, außerorts je nach Straße und Fahrzeug), sofern kein anderes Zeichen steht.`,
  alt: `Zeichen 278 Ende der zulässigen Höchstgeschwindigkeit ${v} km/h: weißer Kreis mit grauer ${v} und schrägen grauen Strichen`,
  svg: () => circleWhite(`${pict(text(50, String(v).length > 2 ? 66 : 68, String(v).length > 2 ? 40 : 50, String(v), GREY), 10, 10, 100)}${endStrokes}`, `Zeichen 278 Ende der zulässigen Höchstgeschwindigkeit ${v} km/h`),
});
/** Halteverbot-Varianten mit Pfeilen */
const haltVariants = (num, kind, name) => [["10", "Anfang"], ["20", "Ende"], ["30", "Mitte"]].map(([s, l]) => ({
  id: `${num}-${s}`, number: `${num}-${s}`, name: `${name} (${l})`, category: cat,
  meaning: `${kind === "x" ? "Halten auf der Fahrbahn und auf dem Seitenstreifen ist verboten." : "Es darf höchstens drei Minuten gehalten werden, zum Ein- oder Aussteigen sowie zum Be- oder Entladen auch länger; Parken ist verboten."} Der weiße Pfeil zeigt ${l === "Anfang" ? "den Anfang der Verbotsstrecke an" : l === "Ende" ? "das Ende der Verbotsstrecke an" : "an, dass das Verbot in beide Richtungen weiter gilt (Wiederholung innerhalb der Strecke)"}.`,
  alt: `Zeichen ${num}-${s} ${name} ${l}: blauer Kreis mit rotem Rand, ${kind === "x" ? "zwei roten Diagonalbalken" : "einem roten Diagonalbalken"} und weißem Pfeil ${l === "Anfang" ? "nach rechts" : l === "Ende" ? "nach links" : "nach links und rechts"}`,
  note: "Pfeilrichtung nach Rechtsaufstellung (Anfang: Pfeil nach rechts, Ende: Pfeil nach links); bei Linksaufstellung amtlich spiegelbildlich.",
  svg: () => halt(kind, s, `Zeichen ${num}-${s} ${name} ${l}`),
}));

// ---------------------------------------------------------------------------------------------
// Katalog
// ---------------------------------------------------------------------------------------------
const bahn = "Das Andreaskreuz steht unmittelbar vor dem Bahnübergang. Der Schienenverkehr hat Vorrang; wer sich nähert, muss mit mäßiger Geschwindigkeit heranfahren und vor dem Andreaskreuz warten, wenn sich ein Schienenfahrzeug nähert, rotes Blinklicht oder Lichtzeichen gegeben werden, Schranken sich senken oder geschlossen sind. Halten ist bis 10 m davor verboten, wenn das Zeichen dadurch verdeckt wird; Parken ist innerorts bis 5 m, außerorts bis 50 m davor und dahinter verboten.";

export default [
  { id: "201-50", number: "201-50", name: "Andreaskreuz (stehend)", category: cat, meaning: bahn, alt: "Zeichen 201-50 Andreaskreuz stehend: weißes X-förmiges Kreuz mit roten Spitzen und schwarzem Rand", svg: () => andreaskreuz(false, false, "Zeichen 201-50 Andreaskreuz stehend") },
  { id: "201-51", number: "201-51", name: "Andreaskreuz (liegend)", category: cat, meaning: `${bahn} Die liegende Form wird aufgestellt, wo für die stehende Form kein Platz ist; die Bedeutung ist gleich.`, alt: "Zeichen 201-51 Andreaskreuz liegend: flaches weißes X-förmiges Kreuz mit roten Spitzen", svg: () => andreaskreuz(true, false, "Zeichen 201-51 Andreaskreuz liegend") },
  { id: "201-52", number: "201-52", name: "Andreaskreuz (stehend) mit Blitzpfeil", category: cat, meaning: `${bahn} Der Blitzpfeil weist auf die elektrische Oberleitung der Bahn hin: Bei hohen Fahrzeugen oder Ladung Abstand zur Oberleitung halten.`, alt: "Zeichen 201-52 Andreaskreuz stehend mit Blitzpfeil: weißes Kreuz mit roten Spitzen und schwarzem Blitzpfeil in der Mitte", note: "Größe und Lage des Blitzpfeils in der Kreuzmitte nach Katalogbild angenähert.", svg: () => andreaskreuz(false, true, "Zeichen 201-52 Andreaskreuz stehend mit Blitzpfeil") },
  { id: "201-53", number: "201-53", name: "Andreaskreuz (liegend) mit Blitzpfeil", category: cat, meaning: `${bahn} Der Blitzpfeil weist auf die elektrische Oberleitung der Bahn hin: Bei hohen Fahrzeugen oder Ladung Abstand zur Oberleitung halten.`, alt: "Zeichen 201-53 Andreaskreuz liegend mit Blitzpfeil: flaches weißes Kreuz mit roten Spitzen und schwarzem Blitzpfeil", note: "Größe und Lage des Blitzpfeils nach Katalogbild angenähert.", svg: () => andreaskreuz(true, true, "Zeichen 201-53 Andreaskreuz liegend mit Blitzpfeil") },
  { id: "205", number: "205", name: "Vorfahrt gewähren", category: cat, meaning: "Wer dieses Zeichen passiert, muss den Fahrzeugen auf der bevorrechtigten Straße Vorfahrt gewähren. Anhalten ist nur nötig, wenn die Verkehrslage es erfordert; die Vorfahrt gilt auch gegenüber Fahrzeugen, die auf der bevorrechtigten Straße abbiegen.", alt: "Zeichen 205 Vorfahrt gewähren: auf der Spitze stehendes weißes Dreieck mit rotem Rand", svg: () => triangleDown("Zeichen 205 Vorfahrt gewähren") },
  { id: "206", number: "206", name: "Halt. Vorfahrt gewähren.", category: cat, meaning: "Es muss angehalten werden, und zwar an der Haltlinie, sonst an der Sichtlinie, von der aus die bevorrechtigte Straße überblickt werden kann. Erst nach dem Anhalten und nachdem den Fahrzeugen auf der bevorrechtigten Straße Vorfahrt gewährt wurde, darf weitergefahren werden; das gilt auch bei freier Sicht.", alt: "Zeichen 206 Halt. Vorfahrt gewähren: rotes Achteck mit weißem Rand und weißer Aufschrift STOP", svg: () => octagonRed(text(60, 74, 38, "STOP", WHITE, "middle", 'letter-spacing="1"'), "Zeichen 206 Halt. Vorfahrt gewähren.") },
  { id: "208", number: "208", name: "Dem Gegenverkehr Vorrang gewähren", category: cat, meaning: "An der Engstelle hat der Gegenverkehr Vorrang. Es darf nur eingefahren werden, wenn der Gegenverkehr dadurch nicht behindert wird; nötigenfalls muss vor der Engstelle gewartet werden.", alt: "Zeichen 208 Dem Gegenverkehr Vorrang gewähren: roter Ring mit rotem Pfeil nach oben und schwarzem Pfeil nach unten", svg: () => circleRed(`<path d="M34 86 V30 L22 30 L40 8 L58 30 H46 V86 Z" fill="${RED}"/><path d="M66 14 V70 H78 L60 92 L42 70 H54 V14 Z" fill="${BLACK}"/>`, "Zeichen 208 Dem Gegenverkehr Vorrang gewähren") },
  { id: "209-10", number: "209-10", name: "Vorgeschriebene Fahrtrichtung links", category: cat, meaning: "An der nächsten Kreuzung oder Einmündung darf nur nach links gefahren werden. Andere Fahrtrichtungen sind verboten.", alt: "Zeichen 209-10 Vorgeschriebene Fahrtrichtung links: blauer Kreis mit weißem Pfeil nach links", svg: () => circleBlue(arrowRot(-90), "Zeichen 209-10 Vorgeschriebene Fahrtrichtung links") },
  { id: "209-20", number: "209-20", name: "Vorgeschriebene Fahrtrichtung rechts", category: cat, meaning: "An der nächsten Kreuzung oder Einmündung darf nur nach rechts gefahren werden. Andere Fahrtrichtungen sind verboten.", alt: "Zeichen 209-20 Vorgeschriebene Fahrtrichtung rechts: blauer Kreis mit weißem Pfeil nach rechts", svg: () => circleBlue(arrowRot(90), "Zeichen 209-20 Vorgeschriebene Fahrtrichtung rechts") },
  { id: "209-30", number: "209-30", name: "Vorgeschriebene Fahrtrichtung geradeaus", category: cat, meaning: "An der nächsten Kreuzung oder Einmündung darf nur geradeaus gefahren werden. Abbiegen ist verboten.", alt: "Zeichen 209-30 Vorgeschriebene Fahrtrichtung geradeaus: blauer Kreis mit weißem Pfeil nach oben", svg: () => circleBlue(arrowUp, "Zeichen 209-30 Vorgeschriebene Fahrtrichtung geradeaus") },
  { id: "211-10", number: "211-10", name: "Vorgeschriebene Fahrtrichtung hier links", category: cat, meaning: "Es muss an dieser Stelle, also unmittelbar vor dem Zeichen, nach links abgebogen werden. Geradeausfahren und Rechtsabbiegen sind verboten.", alt: "Zeichen 211-10 Vorgeschriebene Fahrtrichtung hier links: blauer Kreis mit weißem, nach links abknickendem Pfeil", svg: () => circleBlue(bentLeft, "Zeichen 211-10 Vorgeschriebene Fahrtrichtung hier links") },
  { id: "211-20", number: "211-20", name: "Vorgeschriebene Fahrtrichtung hier rechts", category: cat, meaning: "Es muss an dieser Stelle, also unmittelbar vor dem Zeichen, nach rechts abgebogen werden. Geradeausfahren und Linksabbiegen sind verboten.", alt: "Zeichen 211-20 Vorgeschriebene Fahrtrichtung hier rechts: blauer Kreis mit weißem, nach rechts abknickendem Pfeil", svg: () => circleBlue(mirror(bentLeft), "Zeichen 211-20 Vorgeschriebene Fahrtrichtung hier rechts") },
  { id: "214-10", number: "214-10", name: "Vorgeschriebene Fahrtrichtung geradeaus oder links", category: cat, meaning: "An der nächsten Kreuzung oder Einmündung darf nur geradeaus gefahren oder nach links abgebogen werden. Rechtsabbiegen ist verboten.", alt: "Zeichen 214-10 Vorgeschriebene Fahrtrichtung geradeaus oder links: blauer Kreis mit weißem Pfeil nach oben und Abzweig nach links", svg: () => circleBlue(straightOrLeft, "Zeichen 214-10 Vorgeschriebene Fahrtrichtung geradeaus oder links") },
  { id: "214-20", number: "214-20", name: "Vorgeschriebene Fahrtrichtung geradeaus oder rechts", category: cat, meaning: "An der nächsten Kreuzung oder Einmündung darf nur geradeaus gefahren oder nach rechts abgebogen werden. Linksabbiegen ist verboten.", alt: "Zeichen 214-20 Vorgeschriebene Fahrtrichtung geradeaus oder rechts: blauer Kreis mit weißem Pfeil nach oben und Abzweig nach rechts", svg: () => circleBlue(mirror(straightOrLeft), "Zeichen 214-20 Vorgeschriebene Fahrtrichtung geradeaus oder rechts") },
  { id: "214-30", number: "214-30", name: "Vorgeschriebene Fahrtrichtung links oder rechts", category: cat, meaning: "An der nächsten Kreuzung oder Einmündung darf nur nach links oder nach rechts abgebogen werden. Geradeausfahren ist verboten.", alt: "Zeichen 214-30 Vorgeschriebene Fahrtrichtung links oder rechts: blauer Kreis mit weißem Pfeil, der sich nach links und rechts gabelt", svg: () => circleBlue(leftOrRight, "Zeichen 214-30 Vorgeschriebene Fahrtrichtung links oder rechts") },
  { id: "215", number: "215", name: "Kreisverkehr", category: cat, meaning: "Der Kreisverkehr ist im Uhrzeigersinn, also rechts herum, zu befahren; zusammen mit Zeichen 205 hat der Verkehr im Kreis Vorfahrt. Beim Einfahren darf nicht geblinkt werden, beim Verlassen ist rechts zu blinken; Halten auf der Kreisfahrbahn ist verboten, und in den Kreis darf nicht abbiegend nach links eingefahren werden.", alt: "Zeichen 215 Kreisverkehr: blauer Kreis mit drei weißen, im Kreis angeordneten Pfeilen", svg: () => circleBlue([0, 120, 240].map((a) => `<g transform="rotate(${a} 50 50)"><path d="M50 12 A38 38 0 0 1 84 36" fill="none" stroke="${WHITE}" stroke-width="9"/><path d="M92 20 L92 46 L66 46 Z" fill="${WHITE}" transform="rotate(8 92 46)"/></g>`).join(""), "Zeichen 215 Kreisverkehr", 74) },
  { id: "220-10", number: "220-10", name: "Einbahnstraße (linksweisend)", category: cat, meaning: "Die Straße darf nur in Pfeilrichtung befahren werden, hier nach links. Wer in die Einbahnstraße einfährt, darf sie nur in dieser Richtung durchfahren; Radverkehr in Gegenrichtung ist nur erlaubt, wenn ein Zusatzzeichen ihn freigibt. In Einbahnstraßen darf am linken Fahrbahnrand gehalten und geparkt werden.", alt: "Zeichen 220-10 Einbahnstraße linksweisend: blaues Rechteck mit weißem Pfeil nach links und Aufschrift Einbahnstraße", svg: () => rectBlue(240, 96, `<path d="M200 48 H70 V30 L30 48 L70 66 V48" fill="${WHITE}"/>${text(120, 84, 16, "Einbahnstraße", WHITE)}`, "Zeichen 220-10 Einbahnstraße linksweisend") },
  { id: "220-20", number: "220-20", name: "Einbahnstraße (rechtsweisend)", category: cat, meaning: "Die Straße darf nur in Pfeilrichtung befahren werden, hier nach rechts. Wer in die Einbahnstraße einfährt, darf sie nur in dieser Richtung durchfahren; Radverkehr in Gegenrichtung ist nur erlaubt, wenn ein Zusatzzeichen ihn freigibt. In Einbahnstraßen darf am linken Fahrbahnrand gehalten und geparkt werden.", alt: "Zeichen 220-20 Einbahnstraße rechtsweisend: blaues Rechteck mit weißem Pfeil nach rechts und Aufschrift Einbahnstraße", svg: () => rectBlue(240, 96, `<path d="M40 48 H170 V30 L210 48 L170 66 V48" fill="${WHITE}"/>${text(120, 84, 16, "Einbahnstraße", WHITE)}`, "Zeichen 220-20 Einbahnstraße rechtsweisend") },
  { id: "222-10", number: "222-10", name: "Vorgeschriebene Vorbeifahrt links vorbei", category: cat, meaning: "An dem Hindernis oder der Verkehrsinsel darf nur links vorbeigefahren werden. Rechts vorbei ist verboten.", alt: "Zeichen 222-10 Vorgeschriebene Vorbeifahrt links vorbei: blauer Kreis mit schrägem weißen Pfeil nach links unten", svg: () => circleBlue(arrowRot(-135), "Zeichen 222-10 Vorgeschriebene Vorbeifahrt links vorbei") },
  { id: "222-20", number: "222-20", name: "Vorgeschriebene Vorbeifahrt rechts vorbei", category: cat, meaning: "An dem Hindernis oder der Verkehrsinsel darf nur rechts vorbeigefahren werden. Links vorbei ist verboten.", alt: "Zeichen 222-20 Vorgeschriebene Vorbeifahrt rechts vorbei: blauer Kreis mit schrägem weißen Pfeil nach rechts unten", svg: () => circleBlue(arrowRot(135), "Zeichen 222-20 Vorgeschriebene Vorbeifahrt rechts vorbei") },
  { id: "223-1", number: "223.1", name: "Seitenstreifen befahren", category: cat, meaning: "Der Seitenstreifen darf wie ein Fahrstreifen befahren werden; das Zeichen zeigt die Zahl der Fahrstreifen einschließlich des Seitenstreifens an. Es wird vor allem auf Autobahnen zur zeitweisen Freigabe angeordnet und gilt bis zu seiner Aufhebung.", alt: "Zeichen 223.1 Seitenstreifen befahren: blaues Quadrat mit drei weißen Fahrstreifen und weißen Pfeilen nach oben auf allen drei Streifen", note: "Gezeichnet mit zwei Fahrstreifen und Seitenstreifen (amtliche Varianten 223.1-50 und -51 mit zwei bzw. drei Fahrstreifen).", svg: () => seitenstreifen(1, "Zeichen 223.1 Seitenstreifen befahren") },
  { id: "223-2", number: "223.2", name: "Seitenstreifen nicht mehr befahren", category: cat, meaning: "Die Freigabe des Seitenstreifens endet. Wer auf dem Seitenstreifen fährt, muss ihn verlassen und sich in den Verkehr auf den Fahrstreifen einordnen; der Seitenstreifen darf ab hier nicht mehr befahren werden.", alt: "Zeichen 223.2 Seitenstreifen nicht mehr befahren: blaues Quadrat mit drei weißen Fahrstreifen, der Pfeil des rechten Streifens biegt nach links auf den Fahrstreifen ab", note: "Darstellung des abknickenden Pfeils dem Katalogbild angenähert.", svg: () => seitenstreifen(2, "Zeichen 223.2 Seitenstreifen nicht mehr befahren") },
  { id: "223-3", number: "223.3", name: "Seitenstreifen räumen", category: cat, meaning: "Der Seitenstreifen ist unverzüglich zu verlassen und darf nicht mehr befahren werden, etwa weil er kurz vor einer Anschlussstelle oder Baustelle endet. Rechtzeitig und ohne Gefährdung auf den Fahrstreifen wechseln.", alt: "Zeichen 223.3 Seitenstreifen räumen: blaues Quadrat mit drei weißen Fahrstreifen, der Pfeil des rechten Streifens biegt früh nach links ab, das Ende des Seitenstreifens ist schraffiert", note: "Darstellung (abknickender Pfeil und Schraffur) dem Katalogbild angenähert.", svg: () => seitenstreifen(3, "Zeichen 223.3 Seitenstreifen räumen") },
  { id: "224", number: "224", name: "Haltestelle", category: cat, meaning: "Haltestelle für Straßenbahnen und Linienbusse. Parken ist bis 15 m vor und hinter dem Zeichen verboten; an haltenden Linienbussen darf nur vorsichtig, bei ein- oder aussteigenden Fahrgästen nur mit Schrittgeschwindigkeit und ausreichendem Abstand vorbeigefahren werden. Ein Linienbus mit eingeschaltetem Warnblinklicht darf nicht überholt werden.", alt: "Zeichen 224 Haltestelle: grüner Kreis mit gelbem Ring und grünem H", svg: () => `${svgOpen(120, 120, "Zeichen 224 Haltestelle")}<circle cx="60" cy="60" r="57" fill="${GREEN}" stroke="#9CA3AF" stroke-width="1"/><circle cx="60" cy="60" r="47" fill="${YELLOW}"/><circle cx="60" cy="60" r="38" fill="${GREEN}"/>${text(60, 80, 58, "H", YELLOW)}</svg>` },
  { id: "229", number: "229", name: "Taxenstand", category: cat, meaning: "Hier dürfen sich nur Taxen bereithalten. Für alle anderen Fahrzeuge ist das Halten verboten.", alt: "Zeichen 229 Taxenstand: blaues Rechteck mit weißer Aufschrift TAXI", note: "Amtliches Bild ist ein blaues Rechteck mit der Aufschrift TAXI; Schriftgröße und Seitenverhältnis angenähert.", svg: () => rectBlue(160, 100, text(80, 66, 42, "TAXI", WHITE, "middle", 'letter-spacing="2"'), "Zeichen 229 Taxenstand") },
  { id: "237", number: "237", name: "Radweg", category: cat, meaning: "Radfahrer müssen den Radweg benutzen (Benutzungspflicht) und dürfen nur in der Richtung fahren, in der er freigegeben ist. Andere Fahrzeuge dürfen den Radweg nicht benutzen; Fußgänger dürfen ihn nur benutzen, wenn kein Gehweg vorhanden ist.", alt: "Zeichen 237 Radweg: blauer Kreis mit weißem Fahrrad", svg: () => circleBlue(white(P.bicycle), "Zeichen 237 Radweg") },
  { id: "238", number: "238", name: "Reitweg", category: cat, meaning: "Reiter müssen den Reitweg benutzen. Anderer Verkehr, auch Fußgänger und Radfahrer, darf ihn nicht benutzen.", alt: "Zeichen 238 Reitweg: blauer Kreis mit weißem Reiter auf Pferd", svg: () => circleBlue(rider(WHITE), "Zeichen 238 Reitweg", 80) },
  { id: "239", number: "239", name: "Gehweg", category: cat, meaning: "Der Gehweg ist nur für Fußgänger bestimmt. Anderer Verkehr darf ihn nicht benutzen; Radfahrer müssen absteigen und schieben, sofern nicht ein Zusatzzeichen den Radverkehr freigibt, dann ist mit Schrittgeschwindigkeit zu fahren und auf Fußgänger Rücksicht zu nehmen. Kinder bis acht Jahre müssen, bis zehn Jahre dürfen den Gehweg mit dem Fahrrad benutzen.", alt: "Zeichen 239 Gehweg: blauer Kreis mit weißer gehender Person und Kind", svg: () => circleBlue(pedChild(WHITE), "Zeichen 239 Gehweg", 72) },
  { id: "240", number: "240", name: "Gemeinsamer Geh- und Radweg", category: cat, meaning: "Fußgänger und Radfahrer benutzen denselben Weg. Radfahrer müssen ihn benutzen (Benutzungspflicht) und auf Fußgänger Rücksicht nehmen; sie dürfen sie weder gefährden noch behindern. Anderer Fahrzeugverkehr darf den Weg nicht benutzen.", alt: "Zeichen 240 Gemeinsamer Geh- und Radweg: blauer Kreis, oben weiße Fußgänger, unten weißes Fahrrad, durch eine waagerechte weiße Linie getrennt", svg: () => circleBlue(`<g transform="translate(25 2) scale(0.5)">${pedChild(WHITE)}</g><path d="M12 52 H88" stroke="${WHITE}" stroke-width="3"/><g transform="translate(23 54) scale(0.54)">${white(P.bicycle)}</g>`, "Zeichen 240 Gemeinsamer Geh- und Radweg", 90) },
  { id: "241-30", number: "241-30", name: "Getrennter Rad- und Gehweg (Radweg links)", category: cat, meaning: "Radweg und Gehweg liegen nebeneinander und sind voneinander getrennt, hier der Radweg links. Radfahrer müssen den Radwegteil benutzen, Fußgänger den Gehwegteil; anderer Fahrzeugverkehr darf den Weg nicht benutzen.", alt: "Zeichen 241-30 Getrennter Rad- und Gehweg: blauer Kreis, links weißes Fahrrad, rechts weiße Fußgänger, durch eine senkrechte weiße Linie getrennt", svg: () => circleBlue(`<g transform="translate(0 24) scale(0.5)">${white(P.bicycle)}</g><path d="M50 12 V88" stroke="${WHITE}" stroke-width="3"/><g transform="translate(52 24) scale(0.5)">${pedChild(WHITE)}</g>`, "Zeichen 241-30 Getrennter Rad- und Gehweg, Radweg links", 90) },
  { id: "241-31", number: "241-31", name: "Getrennter Rad- und Gehweg (Radweg rechts)", category: cat, meaning: "Radweg und Gehweg liegen nebeneinander und sind voneinander getrennt, hier der Radweg rechts. Radfahrer müssen den Radwegteil benutzen, Fußgänger den Gehwegteil; anderer Fahrzeugverkehr darf den Weg nicht benutzen.", alt: "Zeichen 241-31 Getrennter Rad- und Gehweg: blauer Kreis, links weiße Fußgänger, rechts weißes Fahrrad, durch eine senkrechte weiße Linie getrennt", svg: () => circleBlue(`<g transform="translate(0 24) scale(0.5)">${pedChild(WHITE)}</g><path d="M50 12 V88" stroke="${WHITE}" stroke-width="3"/><g transform="translate(52 24) scale(0.5)">${white(P.bicycle)}</g>`, "Zeichen 241-31 Getrennter Rad- und Gehweg, Radweg rechts", 90) },
  { id: "242-1", number: "242.1", name: "Beginn einer Fußgängerzone", category: cat, meaning: "In der Fußgängerzone ist nur Fußgängerverkehr erlaubt. Anderer Verkehr darf nur einfahren, wenn ein Zusatzzeichen ihn zulässt (zum Beispiel Lieferverkehr oder Radverkehr frei); dann ist Schrittgeschwindigkeit zu fahren, Fußgänger dürfen weder gefährdet noch behindert werden und haben Vorrang.", alt: "Zeichen 242.1 Beginn einer Fußgängerzone: weißes Rechteck mit blauem Gehweg-Kreis und Aufschrift Fußgängerzone", svg: () => zoneSign(180, 200, blueDisc(pedChild(WHITE), BLUE, 72), 100, "Fußgängerzone", 22, "Zeichen 242.1 Beginn einer Fußgängerzone") },
  { id: "242-2", number: "242.2", name: "Ende einer Fußgängerzone", category: cat, meaning: "Die Fußgängerzone endet; ab hier gelten wieder die allgemeinen Verkehrsregeln. Wer die Zone verlässt, muss sich beim Einfahren auf die Straße wie beim Ausfahren aus einem verkehrsberuhigten Bereich verhalten und andere nicht gefährden.", alt: "Zeichen 242.2 Ende einer Fußgängerzone: weißes Rechteck mit grauem Gehweg-Kreis, grauer Aufschrift Fußgängerzone und schwarzem Schrägstrich", svg: () => zoneSign(180, 200, blueDisc(pedChild(WHITE), GREY, 72), 100, "Fußgängerzone", 22, "Zeichen 242.2 Ende einer Fußgängerzone", { ende: true }) },
  { id: "244-1", number: "244.1", name: "Beginn einer Fahrradstraße", category: cat, meaning: "Die Fahrradstraße ist dem Radverkehr und Elektrokleinstfahrzeugen vorbehalten; anderer Fahrzeugverkehr darf nur einfahren, wenn ein Zusatzzeichen ihn freigibt. Für alle gilt höchstens 30 km/h, Radfahrer dürfen nebeneinander fahren und dürfen weder gefährdet noch behindert werden; nötigenfalls muss der Kraftfahrzeugverkehr die Geschwindigkeit weiter verringern.", alt: "Zeichen 244.1 Beginn einer Fahrradstraße: weißes Rechteck mit blauem Fahrrad-Kreis und Aufschrift Fahrradstraße", svg: () => zoneSign(180, 200, blueDisc(white(P.bicycle)), 100, "Fahrradstraße", 22, "Zeichen 244.1 Beginn einer Fahrradstraße") },
  { id: "244-2", number: "244.2", name: "Ende einer Fahrradstraße", category: cat, meaning: "Die Fahrradstraße endet; ab hier gelten wieder die allgemeinen Verkehrsregeln, insbesondere das Rechtsfahrgebot für Radfahrer und die allgemeine Höchstgeschwindigkeit.", alt: "Zeichen 244.2 Ende einer Fahrradstraße: weißes Rechteck mit grauem Fahrrad-Kreis, grauer Aufschrift Fahrradstraße und schwarzem Schrägstrich", svg: () => zoneSign(180, 200, blueDisc(white(P.bicycle), GREY), 100, "Fahrradstraße", 22, "Zeichen 244.2 Ende einer Fahrradstraße", { ende: true }) },
  { id: "244-3", number: "244.3", name: "Beginn einer Fahrradzone", category: cat, meaning: "In der Fahrradzone gelten auf allen Straßen die Regeln der Fahrradstraße: Vorbehalten für Radverkehr und Elektrokleinstfahrzeuge, anderer Fahrzeugverkehr nur mit Zusatzzeichen, höchstens 30 km/h, Radfahrer dürfen nebeneinander fahren und dürfen weder gefährdet noch behindert werden. Vorfahrt gilt nach den allgemeinen Regeln, in der Regel rechts vor links.", alt: "Zeichen 244.3 Beginn einer Fahrradzone: weißes Rechteck mit blauem Fahrrad-Kreis und Aufschrift ZONE", svg: () => zoneSign(160, 200, blueDisc(white(P.bicycle)), 96, "ZONE", 34, "Zeichen 244.3 Beginn einer Fahrradzone") },
  { id: "244-4", number: "244.4", name: "Ende einer Fahrradzone", category: cat, meaning: "Die Fahrradzone endet; ab hier gelten wieder die allgemeinen Verkehrsregeln.", alt: "Zeichen 244.4 Ende einer Fahrradzone: weißes Rechteck mit grauem Fahrrad-Kreis, grauer Aufschrift ZONE und schwarzem Schrägstrich", svg: () => zoneSign(160, 200, blueDisc(white(P.bicycle), GREY), 96, "ZONE", 34, "Zeichen 244.4 Ende einer Fahrradzone", { ende: true }) },
  { id: "245", number: "245", name: "Bussonderfahrstreifen", category: cat, meaning: "Der Fahrstreifen ist Linienbussen vorbehalten. Andere Fahrzeuge dürfen ihn nicht befahren, sondern nur überqueren oder zum Ein- und Ausfahren aus Grundstücken kurz benutzen; Taxen, Radverkehr oder andere Verkehrsarten dürfen ihn nur benutzen, wenn ein Zusatzzeichen sie freigibt.", alt: "Zeichen 245 Bussonderfahrstreifen: blauer Kreis mit weißem Bus von vorn", svg: () => circleBlue(busFront(WHITE, BLUE), "Zeichen 245 Bussonderfahrstreifen") },
  { id: "250", number: "250", name: "Verbot für Fahrzeuge aller Art", category: cat, meaning: "Fahrzeuge aller Art dürfen nicht einfahren, auch Fahrräder und Gespanne nicht. Krafträder und Fahrräder dürfen geschoben werden; Ausnahmen, etwa Anlieger frei, ergeben sich nur aus einem Zusatzzeichen.", alt: "Zeichen 250 Verbot für Fahrzeuge aller Art: roter Ring auf weißem Grund ohne Symbol", svg: () => circleRed("", "Zeichen 250 Verbot für Fahrzeuge aller Art") },
  { id: "251", number: "251", name: "Verbot für Kraftwagen", category: cat, meaning: "Kraftwagen und sonstige mehrspurige Kraftfahrzeuge dürfen nicht einfahren. Krafträder, Fahrräder und Gespanne sind nicht betroffen.", alt: "Zeichen 251 Verbot für Kraftwagen: roter Ring mit schwarzem Auto von vorn", svg: () => circleRed(P.carFront, "Zeichen 251 Verbot für Kraftwagen") },
  { id: "253", number: "253", name: "Verbot für Kraftfahrzeuge über 3,5 t", category: cat, meaning: "Kraftfahrzeuge mit einer zulässigen Gesamtmasse über 3,5 t einschließlich ihrer Anhänger sowie Zugmaschinen dürfen nicht einfahren. Ausgenommen sind Personenkraftwagen und Kraftomnibusse.", alt: "Zeichen 253 Verbot für Kraftfahrzeuge über 3,5 t: roter Ring mit schwarzem Lkw von vorn", svg: () => circleRed(P.truckFront, "Zeichen 253 Verbot für Kraftfahrzeuge über 3,5 t") },
  { id: "254", number: "254", name: "Verbot für Radverkehr", category: cat, meaning: "Radfahrer dürfen hier nicht fahren. Das Fahrrad darf geschoben werden; Elektrokleinstfahrzeuge sind ebenfalls betroffen.", alt: "Zeichen 254 Verbot für Radverkehr: roter Ring mit schwarzem Fahrrad", svg: () => circleRed(P.bicycle, "Zeichen 254 Verbot für Radverkehr") },
  { id: "255", number: "255", name: "Verbot für Krafträder", category: cat, meaning: "Krafträder, auch mit Beiwagen, Kleinkrafträder und Mofas dürfen nicht einfahren. Sie dürfen geschoben werden.", alt: "Zeichen 255 Verbot für Krafträder: roter Ring mit schwarzem Motorrad mit Fahrer", svg: () => circleRed(P.motorbike, "Zeichen 255 Verbot für Krafträder") },
  { id: "256", number: "256", name: "Verbot für Mofas", category: cat, meaning: "Mofas dürfen hier nicht fahren; sie dürfen geschoben werden. Für Fahrräder und andere Kraftfahrzeuge gilt das Zeichen nicht.", alt: "Zeichen 256 Verbot für Mofas: roter Ring mit schwarzem Mofa in Seitenansicht", svg: () => circleRed(moped(), "Zeichen 256 Verbot für Mofas") },
  { id: "257-50", number: "257-50", name: "Verbot für Reiter", category: cat, meaning: "Reiter dürfen hier nicht reiten. Pferde dürfen geführt werden, sofern kein anderes Verbot entgegensteht.", alt: "Zeichen 257-50 Verbot für Reiter: roter Ring mit schwarzem Reiter auf Pferd", svg: () => circleRed(rider(), "Zeichen 257-50 Verbot für Reiter", 74) },
  { id: "257-51", number: "257-51", name: "Verbot für Gespannfuhrwerke", category: cat, meaning: "Gespannfuhrwerke, also von Tieren gezogene Fahrzeuge, dürfen hier nicht fahren.", alt: "Zeichen 257-51 Verbot für Gespannfuhrwerke: roter Ring mit schwarzem Pferd, das einen Wagen zieht", svg: () => circleRed(gespann(), "Zeichen 257-51 Verbot für Gespannfuhrwerke", 74) },
  { id: "257-52", number: "257-52", name: "Verbot für Viehtrieb", category: cat, meaning: "Vieh darf hier nicht getrieben werden.", alt: "Zeichen 257-52 Verbot für Viehtrieb: roter Ring mit schwarzem Rind", svg: () => circleRed(cow(), "Zeichen 257-52 Verbot für Viehtrieb", 72) },
  { id: "257-53", number: "257-53", name: "Verbot für Kraftfahrzeuge und Züge, die nicht schneller als 25 km/h fahren können", category: cat, meaning: "Kraftfahrzeuge und Züge, die bauartbedingt nicht schneller als 25 km/h fahren können, etwa Zugmaschinen und langsame Arbeitsmaschinen, dürfen nicht einfahren.", alt: "Zeichen 257-53 Verbot für Kraftfahrzeuge und Züge, die nicht schneller als 25 km/h fahren können: roter Ring mit schwarzer Zugmaschine", note: "Zuordnung der Nummer 257-53 zum Verbot für langsame Kraftfahrzeuge (Zugmaschine) nach Verkehrszeichenkatalog; bitte gegen die aktuelle Anlage 2 prüfen.", svg: () => circleRed(tractor(), "Zeichen 257-53 Verbot für Kraftfahrzeuge und Züge bis 25 km/h", 74) },
  { id: "257-54", number: "257-54", name: "Verbot für Kraftomnibusse", category: cat, meaning: "Kraftomnibusse dürfen nicht einfahren. Andere Kraftfahrzeuge sind nicht betroffen.", alt: "Zeichen 257-54 Verbot für Kraftomnibusse: roter Ring mit schwarzem Bus von vorn", svg: () => circleRed(busFront(), "Zeichen 257-54 Verbot für Kraftomnibusse") },
  { id: "257-55", number: "257-55", name: "Verbot für Personenkraftwagen", category: cat, meaning: "Personenkraftwagen dürfen nicht einfahren. Andere Fahrzeuge, etwa Krafträder, Lastkraftwagen und Kraftomnibusse, sind nicht betroffen.", alt: "Zeichen 257-55 Verbot für Personenkraftwagen: roter Ring mit schwarzem Pkw in Seitenansicht", svg: () => circleRed(carSide(), "Zeichen 257-55 Verbot für Personenkraftwagen", 74) },
  { id: "257-56", number: "257-56", name: "Verbot für Personenkraftwagen mit Anhänger", category: cat, meaning: "Personenkraftwagen mit Anhänger, auch mit Wohnwagen, dürfen nicht einfahren. Personenkraftwagen ohne Anhänger sind nicht betroffen.", alt: "Zeichen 257-56 Verbot für Personenkraftwagen mit Anhänger: roter Ring mit schwarzem Pkw und Anhänger in Seitenansicht", svg: () => circleRed(carTrailer(), "Zeichen 257-56 Verbot für Personenkraftwagen mit Anhänger", 78) },
  { id: "257-57", number: "257-57", name: "Verbot für Lastkraftwagen mit Anhänger", category: cat, meaning: "Lastkraftwagen mit Anhänger dürfen nicht einfahren. Lastkraftwagen ohne Anhänger sind nicht betroffen; für Sattelkraftfahrzeuge gilt das Verbot nur, wenn ein Zusatzzeichen dies bestimmt.", alt: "Zeichen 257-57 Verbot für Lastkraftwagen mit Anhänger: roter Ring mit schwarzem Lkw und Anhänger in Seitenansicht", note: "Ob Sattelkraftfahrzeuge erfasst sind, bitte fachlich prüfen.", svg: () => circleRed(truckTrailer(), "Zeichen 257-57 Verbot für Lastkraftwagen mit Anhänger", 80) },
  { id: "257-58", number: "257-58", name: "Verbot für Elektrokleinstfahrzeuge", category: cat, meaning: "Elektrokleinstfahrzeuge, etwa E-Tretroller, dürfen hier nicht fahren. Sie dürfen geschoben werden.", alt: "Zeichen 257-58 Verbot für Elektrokleinstfahrzeuge: roter Ring mit schwarzem E-Tretroller in Seitenansicht", svg: () => circleRed(escooter(), "Zeichen 257-58 Verbot für Elektrokleinstfahrzeuge", 70) },
  { id: "259", number: "259", name: "Verbot für Fußgänger", category: cat, meaning: "Fußgänger dürfen die Straße hier nicht benutzen, weder gehen noch überqueren.", alt: "Zeichen 259 Verbot für Fußgänger: roter Ring mit schwarzer gehender Person", svg: () => circleRed(P.pedestrian, "Zeichen 259 Verbot für Fußgänger", 62) },
  { id: "260", number: "260", name: "Verbot für Krafträder und Kraftwagen", category: cat, meaning: "Krafträder, auch mit Beiwagen, Kleinkrafträder und Mofas sowie Kraftwagen und sonstige mehrspurige Kraftfahrzeuge dürfen nicht einfahren. Fahrräder und Gespanne sind nicht betroffen; Krafträder dürfen geschoben werden.", alt: "Zeichen 260 Verbot für Krafträder und Kraftwagen: roter Ring mit schwarzem Motorrad oben und Auto unten", svg: () => circleRed(`<g transform="translate(0 -14) scale(0.6) translate(34 0)">${P.motorbike}</g><g transform="translate(0 22) scale(0.6) translate(34 0)">${P.carFront}</g>`, "Zeichen 260 Verbot für Krafträder und Kraftwagen", 80) },
  { id: "261", number: "261", name: "Verbot für kennzeichnungspflichtige Kraftfahrzeuge mit gefährlichen Gütern", category: cat, meaning: "Kraftfahrzeuge, die mit orangefarbenen Warntafeln gekennzeichnet sein müssen, weil sie gefährliche Güter befördern, dürfen nicht einfahren. Das gilt zum Beispiel für Tankwagen; ein Zusatzzeichen kann das Verbot einschränken.", alt: "Zeichen 261 Verbot für kennzeichnungspflichtige Kraftfahrzeuge mit gefährlichen Gütern: roter Ring mit schwarzem Lkw von vorn und orangefarbener Warntafel", svg: () => circleRed(truckHazard, "Zeichen 261 Verbot für kennzeichnungspflichtige Kraftfahrzeuge mit gefährlichen Gütern") },
  { id: "262", number: "262", name: "Verbot für Fahrzeuge über angegebene tatsächliche Masse", category: cat, meaning: "Fahrzeuge, deren tatsächliche Masse einschließlich Ladung den angegebenen Wert überschreitet, dürfen nicht einfahren. Maßgeblich ist das tatsächliche Gewicht, nicht die zulässige Gesamtmasse; hier 5,5 t.", alt: "Zeichen 262 Tatsächliche Masse: roter Ring mit schwarzer Aufschrift 5,5 t", note: "Ob bei Zügen die Masse des ganzen Zuges oder des einzelnen Fahrzeugs zählt, bitte fachlich prüfen.", svg: () => circleRed(text(50, 66, 34, "5,5 t"), "Zeichen 262 Tatsächliche Masse", 100) },
  { id: "263", number: "263", name: "Verbot für Fahrzeuge über angegebene tatsächliche Achslast", category: cat, meaning: "Fahrzeuge, bei denen die tatsächliche Achslast einer Achse den angegebenen Wert überschreitet, dürfen nicht einfahren; hier 8 t.", alt: "Zeichen 263 Tatsächliche Achslast: roter Ring mit schwarzer Aufschrift 8 t über einer Achse mit zwei Rädern", svg: () => circleRed(`${text(50, 56, 34, "8 t")}${axle}`, "Zeichen 263 Tatsächliche Achslast", 100) },
  { id: "264", number: "264", name: "Verbot für Fahrzeuge über angegebene tatsächliche Breite", category: cat, meaning: "Fahrzeuge, deren tatsächliche Breite einschließlich Ladung den angegebenen Wert überschreitet, dürfen nicht einfahren; hier 2 m.", alt: "Zeichen 264 Tatsächliche Breite: roter Ring mit schwarzer Aufschrift 2 m zwischen zwei nach innen weisenden schwarzen Dreiecken", svg: () => circleRed(`<path d="M6 50 L22 38 V62 Z M94 50 L78 38 V62 Z" fill="${BLACK}"/>${text(50, 61, 30, "2 m")}`, "Zeichen 264 Tatsächliche Breite", 100) },
  { id: "265", number: "265", name: "Verbot für Fahrzeuge über angegebene tatsächliche Höhe", category: cat, meaning: "Fahrzeuge, deren tatsächliche Höhe einschließlich Ladung den angegebenen Wert überschreitet, dürfen nicht einfahren; hier 3,8 m.", alt: "Zeichen 265 Tatsächliche Höhe: roter Ring mit schwarzer Aufschrift 3,8 m zwischen zwei senkrecht nach innen weisenden schwarzen Dreiecken", svg: () => circleRed(`<path d="M50 6 L38 22 H62 Z M50 94 L38 78 H62 Z" fill="${BLACK}"/>${text(50, 60, 28, "3,8 m")}`, "Zeichen 265 Tatsächliche Höhe", 100) },
  { id: "266", number: "266", name: "Verbot für Fahrzeuge und Züge über angegebene tatsächliche Länge", category: cat, meaning: "Fahrzeuge und Züge, deren tatsächliche Länge einschließlich Ladung den angegebenen Wert überschreitet, dürfen nicht einfahren; hier 10 m. Bei Zügen zählt die Länge des gesamten Zuges.", alt: "Zeichen 266 Tatsächliche Länge: roter Ring mit schwarzem Lkw in Seitenansicht und Aufschrift 10 m", svg: () => circleRed(`<g transform="translate(10 6) scale(0.8)">${truckSide()}</g>${text(50, 92, 26, "10 m")}`, "Zeichen 266 Tatsächliche Länge", 100) },
  { id: "267", number: "267", name: "Verbot der Einfahrt", category: cat, meaning: "In diese Straße darf nicht eingefahren werden; das gilt für Fahrzeuge aller Art, auch für Fahrräder. Das Zeichen steht meist am Ende einer Einbahnstraße; Radverkehr in Gegenrichtung ist nur erlaubt, wenn ein Zusatzzeichen ihn freigibt.", alt: "Zeichen 267 Verbot der Einfahrt: roter Kreis mit weißem waagerechten Balken", svg: () => `${svgOpen(120, 120, "Zeichen 267 Verbot der Einfahrt")}<circle cx="60" cy="60" r="57" fill="${RED}" stroke="#9CA3AF" stroke-width="1"/><rect x="18" y="50" width="84" height="20" rx="2" fill="${WHITE}"/></svg>` },
  { id: "268", number: "268", name: "Schneeketten sind vorgeschrieben", category: cat, meaning: "Kraftfahrzeuge dürfen die Strecke nur mit Schneeketten befahren. Mit Schneeketten darf höchstens 50 km/h gefahren werden, auch wenn keine niedrigere Geschwindigkeit angeordnet ist.", alt: "Zeichen 268 Schneeketten sind vorgeschrieben: blauer Kreis mit weißem Reifen und Schneekette", svg: () => circleBlue(snowChain, "Zeichen 268 Schneeketten sind vorgeschrieben", 78) },
  { id: "269", number: "269", name: "Verbot für Fahrzeuge mit wassergefährdender Ladung", category: cat, meaning: "Fahrzeuge mit wassergefährdender Ladung, etwa Tankwagen mit Heizöl oder Kraftstoff, dürfen nicht einfahren. Das Zeichen schützt Wasserschutzgebiete; Mengen und Ausnahmen kann ein Zusatzzeichen nennen.", alt: "Zeichen 269 Verbot für Fahrzeuge mit wassergefährdender Ladung: roter Ring mit schwarzem Lkw von vorn und weißen Wellenlinien", note: "Piktogramm (Lkw mit Wassersymbol) dem amtlichen Bild angenähert; Mengenschwelle bitte fachlich prüfen.", svg: () => circleRed(truckWater, "Zeichen 269 Verbot für Fahrzeuge mit wassergefährdender Ladung") },
  { id: "270-1", number: "270.1", name: "Beginn einer Verkehrsverbotszone zur Verminderung schädlicher Luftverunreinigungen (Umweltzone)", category: cat, meaning: "In die Umweltzone dürfen Kraftfahrzeuge nur einfahren, wenn sie mit der Plakette gekennzeichnet sind, die das Zusatzzeichen freigibt (in der Regel die grüne Plakette). Fahrzeuge ohne oder mit einer nicht freigegebenen Plakette dürfen die Zone nicht befahren.", alt: "Zeichen 270.1 Umweltzone: weißes Rechteck mit Aufschrift Umwelt, rotem Ring mit Auto und Aufschrift ZONE", svg: () => zoneSign(160, 214, redDisc(P.carFront), 90, "ZONE", 32, "Zeichen 270.1 Beginn einer Umweltzone", { top: 54, header: text(80, 42, 26, "Umwelt") }) },
  { id: "270-2", number: "270.2", name: "Ende einer Verkehrsverbotszone zur Verminderung schädlicher Luftverunreinigungen (Umweltzone)", category: cat, meaning: "Die Umweltzone endet; ab hier dürfen auch Kraftfahrzeuge ohne freigegebene Plakette wieder fahren.", alt: "Zeichen 270.2 Ende der Umweltzone: weißes Rechteck mit grauer Aufschrift Umwelt, grauem Ring mit Auto, grauer Aufschrift ZONE und schwarzem Schrägstrich", svg: () => zoneSign(160, 214, redDisc(grey(P.carFront), GREY), 90, "ZONE", 32, "Zeichen 270.2 Ende einer Umweltzone", { top: 54, header: text(80, 42, 26, "Umwelt", GREY), ende: true }) },
  { id: "272", number: "272", name: "Verbot des Wendens", category: cat, meaning: "Wenden ist verboten. Das Verbot gilt an der Stelle, an der das Zeichen steht, bis zur nächsten Kreuzung oder Einmündung beziehungsweise bis zu seiner Aufhebung.", alt: "Zeichen 272 Verbot des Wendens: roter Ring mit schwarzem U-förmigem Pfeil und rotem Schrägstrich", svg: () => circleRed(`<path d="M30 82 V44 A20 20 0 0 1 70 44 V82" fill="none" stroke="${BLACK}" stroke-width="12"/><path d="M24 78 H36 L30 92 Z M64 78 H76 L70 92 Z" fill="${BLACK}"/>`, "Zeichen 272 Verbot des Wendens", 68, `<rect x="16" y="55" width="88" height="9" fill="${RED}" transform="rotate(-45 60 60)"/>`) },
  { id: "273", number: "273", name: "Verbot des Unterschreitens des angegebenen Mindestabstandes", category: cat, meaning: "Kraftfahrzeuge mit einer zulässigen Gesamtmasse über 3,5 t, ausgenommen Personenkraftwagen und Kraftomnibusse, dürfen den angegebenen Mindestabstand zu vorausfahrenden Kraftfahrzeugen nicht unterschreiten; hier 70 m. Das Zeichen steht zum Beispiel vor Tunneln und auf Gefällstrecken.", alt: "Zeichen 273 Mindestabstand: roter Ring mit zwei schwarzen Autos hintereinander und Aufschrift 70 m", note: "Fahrzeugkreis (Kfz über 3,5 t ohne Pkw und Busse) nach Anlage 2; bitte prüfen.", svg: () => circleRed(`<g transform="translate(29 0) scale(0.42)">${P.carFront}</g>${text(50, 60, 24, "70 m")}<g transform="translate(29 58) scale(0.42)">${P.carFront}</g>`, "Zeichen 273 Verbot des Unterschreitens des angegebenen Mindestabstandes", 100) },
  ...[5, 10, 20, 30, 40, 50, 60, 70, 80, 100, 120, 130].map(tempo),
  { id: "274-1", number: "274.1", name: "Beginn einer Tempo 30-Zone", category: cat, meaning: "In der gesamten Zone darf nicht schneller als 30 km/h gefahren werden; das gilt bis zum Zeichen 274.2. In Tempo 30-Zonen gilt in der Regel rechts vor links, Fahrbahnmarkierungen und Ampeln fehlen meist.", alt: "Zeichen 274.1 Beginn einer Tempo 30-Zone: weißes Rechteck mit rotem Ring, schwarzer 30 und Aufschrift ZONE", svg: () => zoneSign(160, 200, redDisc(text(50, 68, 50, "30"), RED, 100), 96, "ZONE", 34, "Zeichen 274.1 Beginn einer Tempo 30-Zone") },
  { id: "274-2", number: "274.2", name: "Ende einer Tempo 30-Zone", category: cat, meaning: "Die Tempo 30-Zone endet; ab hier gilt wieder die allgemeine Höchstgeschwindigkeit, innerorts 50 km/h, sofern kein anderes Zeichen etwas anderes anordnet.", alt: "Zeichen 274.2 Ende einer Tempo 30-Zone: weißes Rechteck mit grauem Ring, grauer 30, grauer Aufschrift ZONE und schwarzem Schrägstrich", svg: () => zoneSign(160, 200, redDisc(text(50, 68, 50, "30", GREY), GREY, 100), 96, "ZONE", 34, "Zeichen 274.2 Ende einer Tempo 30-Zone", { ende: true }) },
  { id: "275", number: "275", name: "Vorgeschriebene Mindestgeschwindigkeit", category: cat, meaning: "Kraftfahrzeuge dürfen nicht langsamer als angegeben fahren, hier 30 km/h, sofern nicht Straßen-, Verkehrs-, Sicht- oder Wetterverhältnisse dazu zwingen. Fahrzeuge, die diese Geschwindigkeit nicht erreichen können, dürfen die Straße oder den Fahrstreifen nicht benutzen.", alt: "Zeichen 275 Vorgeschriebene Mindestgeschwindigkeit: blauer Kreis mit weißer 30", svg: () => circleBlue(text(50, 68, 50, "30", WHITE), "Zeichen 275 Vorgeschriebene Mindestgeschwindigkeit 30 km/h", 100) },
  { id: "276", number: "276", name: "Überholverbot für Kraftfahrzeuge aller Art", category: cat, meaning: "Kraftfahrzeuge aller Art dürfen mehrspurige Kraftfahrzeuge und Krafträder mit Beiwagen nicht überholen. Das Überholen einspuriger Fahrzeuge, etwa von Fahrrädern, Mofas oder Krafträdern ohne Beiwagen, bleibt erlaubt.", alt: "Zeichen 276 Überholverbot für Kraftfahrzeuge aller Art: roter Ring mit rotem Auto links und schwarzem Auto rechts", svg: () => circleRed(`<g transform="translate(-22 0) scale(0.62) translate(30 30)">${P.carFrontRed}</g><g transform="translate(22 0) scale(0.62) translate(30 30)">${P.carFront}</g>`, "Zeichen 276 Überholverbot für Kraftfahrzeuge aller Art", 90) },
  { id: "277", number: "277", name: "Überholverbot für Kraftfahrzeuge über 3,5 t", category: cat, meaning: "Kraftfahrzeuge mit einer zulässigen Gesamtmasse über 3,5 t, ausgenommen Personenkraftwagen und Kraftomnibusse, dürfen mehrspurige Kraftfahrzeuge und Krafträder mit Beiwagen nicht überholen. Für Pkw gilt das Verbot nicht.", alt: "Zeichen 277 Überholverbot für Kraftfahrzeuge über 3,5 t: roter Ring mit rotem Lkw links und schwarzem Auto rechts", svg: () => circleRed(`<g transform="translate(-22 0) scale(0.62) translate(30 30)">${P.truckFront.replaceAll(BLACK, RED)}</g><g transform="translate(22 0) scale(0.62) translate(30 30)">${P.carFront}</g>`, "Zeichen 277 Überholverbot für Kraftfahrzeuge über 3,5 t", 90) },
  { id: "277-1", number: "277.1", name: "Verbot des Überholens von einspurigen Fahrzeugen für mehrspurige Kraftfahrzeuge und Krafträder mit Beiwagen", category: cat, meaning: "Mehrspurige Kraftfahrzeuge und Krafträder mit Beiwagen dürfen einspurige Fahrzeuge, also Fahrräder, Elektrokleinstfahrzeuge und Krafträder ohne Beiwagen, nicht überholen. Das Zeichen steht dort, wo der Seitenabstand beim Überholen nicht eingehalten werden kann.", alt: "Zeichen 277.1 Überholverbot bezogen auf Radverkehr: roter Ring mit rotem Auto links sowie schwarzem Fahrrad und Motorrad rechts", svg: () => circleRed(`<g transform="translate(-24 4) scale(0.64) translate(30 30)">${P.carFrontRed}</g><g transform="translate(50 6) scale(0.48)">${P.bicycle}</g><g transform="translate(50 50) scale(0.48)">${P.motorbike}</g>`, "Zeichen 277.1 Verbot des Überholens von einspurigen Fahrzeugen", 96) },
  ...[30, 50, 60, 70, 80, 100, 120].map(tempoEnd),
  { id: "279", number: "279", name: "Ende der vorgeschriebenen Mindestgeschwindigkeit", category: cat, meaning: "Hebt die zuvor angeordnete Mindestgeschwindigkeit auf; ab hier dürfen auch langsamere Fahrzeuge die Straße oder den Fahrstreifen wieder benutzen.", alt: "Zeichen 279 Ende der vorgeschriebenen Mindestgeschwindigkeit: blauer Kreis mit weißer 30 und rotem Schrägstrich", svg: () => `${svgOpen(120, 120, "Zeichen 279 Ende der vorgeschriebenen Mindestgeschwindigkeit")}<defs><clipPath id="mc"><circle cx="60" cy="60" r="57"/></clipPath></defs><circle cx="60" cy="60" r="57" fill="${BLUE}" stroke="#9CA3AF" stroke-width="1"/><circle cx="60" cy="60" r="53" fill="none" stroke="${WHITE}" stroke-width="3"/>${pict(text(50, 68, 50, "30", WHITE), 10, 10, 100)}<g clip-path="url(#mc)"><rect x="54" y="0" width="12" height="120" fill="${RED}" transform="rotate(45 60 60)"/></g></svg>` },
  { id: "280", number: "280", name: "Ende des Überholverbots für Kraftfahrzeuge aller Art", category: cat, meaning: "Hebt das mit Zeichen 276 angeordnete Überholverbot auf. Überholen ist wieder erlaubt, sofern es die allgemeinen Regeln und die Verkehrslage zulassen.", alt: "Zeichen 280 Ende des Überholverbots für Kraftfahrzeuge aller Art: weißer Kreis mit zwei grauen Autos und schrägen grauen Strichen", svg: () => circleWhite(`${pict(`<g transform="translate(-22 0) scale(0.62) translate(30 30)">${grey(P.carFront)}</g><g transform="translate(22 0) scale(0.62) translate(30 30)">${grey(P.carFront)}</g>`, 15, 15, 90)}${endStrokes}`, "Zeichen 280 Ende des Überholverbots für Kraftfahrzeuge aller Art") },
  { id: "281", number: "281", name: "Ende des Überholverbots für Kraftfahrzeuge über 3,5 t", category: cat, meaning: "Hebt das mit Zeichen 277 angeordnete Überholverbot für Kraftfahrzeuge über 3,5 t auf.", alt: "Zeichen 281 Ende des Überholverbots für Kraftfahrzeuge über 3,5 t: weißer Kreis mit grauem Lkw und grauem Auto und schrägen grauen Strichen", svg: () => circleWhite(`${pict(`<g transform="translate(-22 0) scale(0.62) translate(30 30)">${grey(P.truckFront)}</g><g transform="translate(22 0) scale(0.62) translate(30 30)">${grey(P.carFront)}</g>`, 15, 15, 90)}${endStrokes}`, "Zeichen 281 Ende des Überholverbots für Kraftfahrzeuge über 3,5 t") },
  { id: "281-1", number: "281.1", name: "Ende des Verbots des Überholens von einspurigen Fahrzeugen", category: cat, meaning: "Hebt das mit Zeichen 277.1 angeordnete Verbot auf, einspurige Fahrzeuge zu überholen. Beim Überholen von Radfahrern gilt weiterhin der Mindestseitenabstand von 1,5 m innerorts und 2 m außerorts.", alt: "Zeichen 281.1 Ende des Überholverbots bezogen auf Radverkehr: weißer Kreis mit grauem Auto, Fahrrad und Motorrad und schrägen grauen Strichen", svg: () => circleWhite(`${pict(`<g transform="translate(-24 4) scale(0.64) translate(30 30)">${grey(P.carFront)}</g><g transform="translate(50 6) scale(0.48)">${grey(P.bicycle)}</g><g transform="translate(50 50) scale(0.48)">${grey(P.motorbike)}</g>`, 12, 12, 96)}${endStrokes}`, "Zeichen 281.1 Ende des Verbots des Überholens von einspurigen Fahrzeugen") },
  { id: "282", number: "282", name: "Ende aller Streckenverbote", category: cat, meaning: "Hebt alle durch Zeichen angeordneten Streckenverbote auf, also Geschwindigkeitsbeschränkungen und Überholverbote. Danach gelten wieder die allgemeinen Regeln; Zonenregelungen und Halteverbote sind nicht betroffen.", alt: "Zeichen 282 Ende aller Streckenverbote: weißer Kreis mit schrägen grauen Strichen", svg: () => circleWhite(endStrokes, "Zeichen 282 Ende aller Streckenverbote") },
  { id: "283", number: "283", name: "Absolutes Halteverbot", category: cat, meaning: "Halten auf der Fahrbahn und auf dem Seitenstreifen ist verboten, auch kurz zum Be- oder Entladen oder zum Ein- und Aussteigen. Das Verbot gilt auf der Straßenseite, auf der das Zeichen steht, bis zu seinem Ende; verkehrsbedingtes Warten ist kein Halten.", alt: "Zeichen 283 Absolutes Halteverbot: blauer Kreis mit rotem Rand und zwei roten Diagonalbalken", svg: () => halt("x", "", "Zeichen 283 Absolutes Halteverbot") },
  ...haltVariants("283", "x", "Absolutes Halteverbot"),
  { id: "286", number: "286", name: "Eingeschränktes Halteverbot", category: cat, meaning: "Auf der Fahrbahn darf höchstens drei Minuten gehalten werden; zum Ein- oder Aussteigen und zum Be- oder Entladen auch länger, sofern das ohne Verzögerung geschieht. Parken ist verboten; das Verbot gilt auf der Straßenseite, auf der das Zeichen steht.", alt: "Zeichen 286 Eingeschränktes Halteverbot: blauer Kreis mit rotem Rand und einem roten Diagonalbalken von links oben nach rechts unten", note: "Der Balken verläuft hier von links oben nach rechts unten; die Bausteinvariante haltverbot() im Kit zeichnet ihn spiegelbildlich.", svg: () => halt("\\", "", "Zeichen 286 Eingeschränktes Halteverbot") },
  ...haltVariants("286", "\\", "Eingeschränktes Halteverbot"),
  { id: "290-1", number: "290.1", name: "Beginn einer Zone mit eingeschränktem Halteverbot", category: cat, meaning: "In der gesamten Zone gilt eingeschränktes Halteverbot: Parken ist nur auf den gekennzeichneten Flächen erlaubt, oft mit Parkscheibe oder Parkschein nach Zusatzzeichen; Halten bis zu drei Minuten sowie zum Ein- und Aussteigen oder Be- und Entladen bleibt erlaubt.", alt: "Zeichen 290.1 Zone mit eingeschränktem Halteverbot: weißes Rechteck mit Halteverbot-Kreis und Aufschrift ZONE", svg: () => zoneSign(160, 200, haltInner(), 96, "ZONE", 34, "Zeichen 290.1 Beginn einer Zone mit eingeschränktem Halteverbot") },
  { id: "290-2", number: "290.2", name: "Ende einer Zone mit eingeschränktem Halteverbot", category: cat, meaning: "Die Zone mit eingeschränktem Halteverbot endet; ab hier gelten wieder die allgemeinen Halte- und Parkregeln.", alt: "Zeichen 290.2 Ende einer Zone mit eingeschränktem Halteverbot: weißes Rechteck mit grauem Halteverbot-Kreis, grauer Aufschrift ZONE und schwarzem Schrägstrich", svg: () => zoneSign(160, 200, haltInner("#9CA3AF", GREY), 96, "ZONE", 34, "Zeichen 290.2 Ende einer Zone mit eingeschränktem Halteverbot", { ende: true }) },
  { id: "293", number: "293", name: "Fußgängerüberweg", category: cat, meaning: "Am Zebrastreifen haben Fußgänger und Rollstuhlfahrer, die den Überweg erkennbar benutzen wollen, Vorrang; Fahrzeuge müssen mit mäßiger Geschwindigkeit heranfahren und nötigenfalls warten. Überholen am Überweg und Halten auf dem Überweg sowie bis 5 m davor sind verboten; bei stockendem Verkehr darf nicht auf den Überweg gefahren werden.", alt: "Zeichen 293 Fußgängerüberweg: weiße Streifen quer über grauer Fahrbahn (Zebrastreifen)", svg: () => marking(`${laneEdges}${[0, 1, 2, 3, 4, 5].map((i) => `<rect x="${17 + i * 15}" y="30" width="9" height="60" fill="${WHITE}"/>`).join("")}`, "Zeichen 293 Fußgängerüberweg") },
  { id: "294", number: "294", name: "Haltlinie", category: cat, meaning: "Wo angehalten werden muss, etwa bei Zeichen 206, rotem Lichtzeichen oder geschlossener Schranke, ist an der Haltlinie zu halten. Die Linie darf beim Anhalten nicht überfahren werden; wer auf ihr steht, muss den Überblick von dort aus gewinnen.", alt: "Zeichen 294 Haltlinie: breite weiße Querlinie auf grauer Fahrbahn, rechts der gestrichelten Mittellinie", svg: () => marking(`${laneEdges}<path d="M60 0 V120" stroke="${WHITE}" stroke-width="3" stroke-dasharray="10 8"/><rect x="60" y="66" width="52" height="9" fill="${WHITE}"/>`, "Zeichen 294 Haltlinie") },
  { id: "295", number: "295", name: "Fahrstreifenbegrenzung und Fahrbahnbegrenzung", category: cat, meaning: "Die durchgezogene Linie darf nicht überfahren werden; als Fahrstreifenbegrenzung darf auch nicht über sie hinweg gefahren oder überholt werden. Als Fahrbahnbegrenzung trennt sie die Fahrbahn vom Seitenstreifen, der dann nicht befahren werden darf (Ausnahmen für land- und forstwirtschaftliche Fahrzeuge und Radfahrer). Halten ist links neben der Linie verboten, wenn zwischen Fahrzeug und Linie nicht mindestens 3 m bleiben.", alt: "Zeichen 295 Fahrstreifenbegrenzung: durchgezogene weiße Linie in der Mitte der grauen Fahrbahn", svg: () => marking(`${laneEdges}<path d="M60 0 V120" stroke="${WHITE}" stroke-width="5"/>`, "Zeichen 295 Fahrstreifenbegrenzung und Fahrbahnbegrenzung") },
  { id: "296", number: "296", name: "Einseitige Fahrstreifenbegrenzung", category: cat, meaning: "Die durchgezogene Linie darf nur von der Seite überfahren werden, auf der die unterbrochene Linie liegt, etwa zum Überholen; von der Seite der durchgezogenen Linie darf sie nicht überfahren werden.", alt: "Zeichen 296 Einseitige Fahrstreifenbegrenzung: durchgezogene und daneben gestrichelte weiße Linie auf grauer Fahrbahn", svg: () => marking(`${laneEdges}<path d="M55 0 V120" stroke="${WHITE}" stroke-width="5"/><path d="M65 0 V120" stroke="${WHITE}" stroke-width="4" stroke-dasharray="14 10"/>`, "Zeichen 296 Einseitige Fahrstreifenbegrenzung") },
  { id: "297", number: "297", name: "Pfeile (Richtungspfeile)", category: cat, meaning: "Die Pfeile ordnen an, sich vor der Kreuzung oder Einmündung entsprechend der beabsichtigten Fahrtrichtung einzuordnen. Wer sich in einem so markierten Fahrstreifen eingeordnet hat, darf nur in Pfeilrichtung weiterfahren; die Pfeile zeigen also, welche Fahrtrichtungen von diesem Fahrstreifen aus erlaubt sind.", alt: "Zeichen 297 Pfeile: weiße Richtungspfeile auf grauer Fahrbahn, links geradeaus, rechts nach rechts abknickend", svg: () => marking(`${laneEdges}<path d="M60 0 V120" stroke="${WHITE}" stroke-width="3" stroke-dasharray="10 8"/><path d="M34 104 V44 M34 22 L23 46 H45 Z" stroke="${WHITE}" stroke-width="7" fill="${WHITE}" stroke-linejoin="round"/><path d="M86 104 V60 Q86 46 100 46" stroke="${WHITE}" stroke-width="7" fill="none"/><path d="M96 34 L112 46 L96 58 Z" fill="${WHITE}"/>`, "Zeichen 297 Pfeile") },
  { id: "297-1", number: "297.1", name: "Vorankündigungspfeil", category: cat, meaning: "Kündigt eine Fahrstreifenbegrenzung (durchgezogene Linie) an; sie ist in Pfeilrichtung versetzt zu erwarten. Wer sich noch links davon befindet, etwa beim Überholen, muss sich rechtzeitig wieder rechts einordnen.", alt: "Zeichen 297.1 Vorankündigungspfeil: weißer Pfeil auf grauer Fahrbahn, dessen Spitze schräg nach rechts oben weist", svg: () => marking(`${laneEdges}<path d="M60 0 V40" stroke="${WHITE}" stroke-width="5"/><path d="M60 40 V120" stroke="${WHITE}" stroke-width="4" stroke-dasharray="14 10"/><path d="M30 108 V58 L50 38" stroke="${WHITE}" stroke-width="7" fill="none" stroke-linejoin="round"/><path d="M57 31 L38.5 34.5 L53.5 49.5 Z" fill="${WHITE}"/>`, "Zeichen 297.1 Vorankündigungspfeil") },
  { id: "298", number: "298", name: "Sperrfläche", category: cat, meaning: "Sperrflächen dürfen nicht befahren werden; auch Halten und Parken darauf sind verboten. Sie trennen zum Beispiel Fahrstreifen oder sichern Verkehrsinseln und Abzweigungen.", alt: "Zeichen 298 Sperrfläche: weiß umrandete, schräg schraffierte Fläche auf grauer Fahrbahn", svg: () => marking(`<defs><clipPath id="sp"><path d="M14 16 H106 L70 112 H50 Z"/></clipPath></defs>${laneEdges}<g clip-path="url(#sp)" stroke="${WHITE}" stroke-width="4">${[0, 1, 2, 3, 4, 5, 6, 7, 8].map((i) => `<path d="M${-40 + i * 22} 120 L${60 + i * 22} 0"/>`).join("")}</g><path d="M14 16 H106 L70 112 H50 Z" fill="none" stroke="${WHITE}" stroke-width="5" stroke-linejoin="round"/>`, "Zeichen 298 Sperrfläche") },
  { id: "299", number: "299", name: "Grenzmarkierung für Halt- oder Parkverbote", category: cat, meaning: "Die Zickzacklinie kennzeichnet den Bereich eines Halt- oder Parkverbots, etwa an Haltestellen, Grundstückszufahrten oder Feuerwehrzufahrten. Innerhalb der Markierung darf nicht gehalten, an Haltestellen nicht geparkt werden; sie verdeutlicht ein bestehendes Verbot.", alt: "Zeichen 299 Grenzmarkierung für Halt- oder Parkverbote: weiße Zickzacklinie am rechten Fahrbahnrand auf grauem Asphalt", svg: () => marking(`<rect x="104" y="0" width="16" height="120" fill="#9CA3AF"/><path d="M8 0 V120" stroke="${WHITE}" stroke-width="3"/><path d="M62 8 H100 L62 30 L100 52 L62 74 L100 96 L62 112 H100" fill="none" stroke="${WHITE}" stroke-width="4" stroke-linejoin="round"/>`, "Zeichen 299 Grenzmarkierung für Halt- oder Parkverbote") },
];
